#pragma once

namespace navi {

// buildin macro is for navi only
// do not use these macro in app
// use REGISTER_KERNEL REGISTER_RESOURCE REGISTER_TYPE instead.

#define REGISTER_BUILDIN_KERNEL(NAME) REGISTER_BUILDIN_KERNEL_HELPER(__COUNTER__, NAME)
#define REGISTER_BUILDIN_KERNEL_HELPER(ctr, NAME) REGISTER_KERNEL_UNIQ(ctr, NAME, true)

#define REGISTER_BUILDIN_RESOURCE(NAME) REGISTER_BUILDIN_RESOURCE_HELPER(__COUNTER__, NAME)
#define REGISTER_BUILDIN_RESOURCE_HELPER(ctr, NAME) REGISTER_RESOURCE_UNIQ(ctr, NAME, true)

#define REGISTER_BUILDIN_TYPE(NAME) REGISTER_BUILDIN_TYPE_HELPER(__COUNTER__, NAME)
#define REGISTER_BUILDIN_TYPE_HELPER(ctr, NAME) REGISTER_TYPE_UNIQ(ctr, NAME, true)

}

